    conformity::Union{Absent,InterruptibleStandardLoadConformity,Nothing} = ABSENT
    constant_active_power::Union{Absent,Float64,Nothing} = ABSENT
    constant_reactive_power::Union{Absent,Float64,Nothing} = ABSENT
